-- tech-interview-for-developer(https://github.com/gyoogle/tech-interview-for-developer) 레포의
-- Network / Database / Operating System / Data Structure / Language(JavaScript 기준) 주제를 참고하여
-- cs_questions 테이블에 카테고리별 문제를 보강한다. frontend 카테고리는 JavaScript 언어 문제를 포함한다.

INSERT INTO public.cs_questions (category, question, answer, question_type, choices, correct_index) VALUES
-- ================= network =================
('network', 'OSI 7계층 중 데이터의 전송 경로를 결정하고 라우팅을 담당하는 계층은?', '네트워크 계층', 'multiple-choice', ARRAY['물리 계층', '데이터 링크 계층', '네트워크 계층', '전송 계층'], 2),
('network', 'TCP 3-way handshake에서 두 번째 단계에 전송되는 플래그 조합은?', 'SYN+ACK', 'multiple-choice', ARRAY['SYN', 'SYN+ACK', 'ACK', 'FIN+ACK'], 1),
('network', 'HTTP와 HTTPS의 가장 큰 차이점은?', 'HTTPS는 TLS/SSL로 암호화된 통신을 한다', 'multiple-choice', ARRAY['HTTPS는 UDP를 사용한다', 'HTTPS는 TLS/SSL로 암호화된 통신을 한다', 'HTTP는 포트 443을 사용한다', 'HTTPS는 상태를 저장한다'], 1),
('network', 'DNS의 역할로 가장 적절한 것은?', 'IP 주소를 도메인 이름으로 변환하거나 그 반대를 수행한다', 'multiple-choice', ARRAY['IP 주소를 도메인 이름으로 변환하거나 그 반대를 수행한다', '패킷의 오류를 검출한다', '네트워크 대역폭을 할당한다', '암호화 키를 교환한다'], 0),
('network', 'TCP 흐름 제어(Flow Control)의 목적은?', '송신자가 수신자의 처리 속도를 초과해 데이터를 보내지 않도록 한다', 'multiple-choice', ARRAY['네트워크 혼잡을 방지한다', '송신자가 수신자의 처리 속도를 초과해 데이터를 보내지 않도록 한다', '패킷의 경로를 최적화한다', '데이터를 압축한다'], 1),
('network', '다음 중 비대칭키(공개키) 암호화 방식에 대한 설명으로 옳은 것은?', '공개키로 암호화한 데이터는 개인키로만 복호화할 수 있다', 'multiple-choice', ARRAY['암호화와 복호화에 동일한 키를 사용한다', '공개키로 암호화한 데이터는 개인키로만 복호화할 수 있다', '대칭키보다 항상 속도가 빠르다', '키 분배 문제가 없다'], 1),
('network', '로드 밸런싱(Load Balancing)의 주된 목적은?', '단일 서버에 트래픽이 집중되지 않도록 여러 서버에 부하를 분산시킨다', 'multiple-choice', ARRAY['단일 서버에 트래픽이 집중되지 않도록 여러 서버에 부하를 분산시킨다', '데이터베이스 정규화를 수행한다', '클라이언트의 요청을 캐싱한다', '암호화 통신을 지원한다'], 0),
('network', 'Blocking I/O와 Non-blocking I/O에 대한 설명으로 옳은 것은?', 'Non-blocking I/O는 호출 즉시 결과 여부와 상관없이 리턴한다', 'multiple-choice', ARRAY['Blocking I/O는 작업이 끝날 때까지 호출자가 대기하지 않는다', 'Non-blocking I/O는 호출 즉시 결과 여부와 상관없이 리턴한다', 'Blocking I/O와 Non-blocking I/O는 동기/비동기와 동일한 개념이다', 'Non-blocking I/O는 항상 멀티스레드를 필요로 한다'], 1),
('network', 'TLS Handshake 과정에서 사용되는 것이 아닌 것은?', 'ARP 요청', 'multiple-choice', ARRAY['인증서 교환', '세션키 생성', 'ARP 요청', 'Cipher Suite 협상'], 2),
('network', 'UDP의 특징으로 옳은 것은?', '비연결형이며 오버헤드가 적어 빠르다', 'multiple-choice', ARRAY['연결 지향적이며 신뢰성을 보장한다', '흐름제어와 혼잡제어를 수행한다', '비연결형이며 오버헤드가 적어 빠르다', '반드시 3-way handshake를 수행한다'], 2),
('network', 'TCP의 3-way handshake 과정을 순서대로 설명하시오.', '1) 클라이언트가 서버에 SYN 패킷을 보낸다. 2) 서버가 SYN을 받고 SYN+ACK 패킷으로 응답한다. 3) 클라이언트가 이를 받고 ACK 패킷을 보내 연결을 확립한다. 연결 종료 시에는 4-way handshake로 양쪽이 FIN/ACK를 주고받으며 종료한다.', 'short-answer', NULL, NULL),
('network', '동기(Synchronous)/비동기(Asynchronous)와 블로킹(Blocking)/논블로킹(Non-blocking)의 차이를 설명하시오.', '동기/비동기는 작업 완료 여부를 누가 확인하는지에 대한 개념으로, 동기는 호출자가 직접 결과를 확인하고 비동기는 콜백 등으로 통보받는다. 블로킹/논블로킹은 호출된 함수가 제어권을 언제 돌려주는지에 대한 개념으로, 블로킹은 작업이 끝날 때까지 제어권을 넘기지 않고 논블로킹은 즉시 돌려준다. 두 개념은 서로 다른 축이라 네 가지 조합이 모두 가능하다.', 'short-answer', NULL, NULL),
('network', '대칭키 암호화와 공개키(비대칭키) 암호화의 차이와 각각의 장단점을 설명하시오.', '대칭키 암호화는 암호화와 복호화에 같은 키를 사용해 속도가 빠르지만 키를 안전하게 전달하는 문제가 있다. 공개키 암호화는 공개키와 개인키 쌍을 사용해 키 분배 문제를 해결하지만 연산량이 많아 속도가 느리다. 실제로는 TLS처럼 공개키로 세션키를 교환한 뒤 대칭키로 실제 데이터를 암호화하는 하이브리드 방식을 주로 사용한다.', 'short-answer', NULL, NULL),
('network', 'HTTP는 무상태(Stateless) 프로토콜이다. 이로 인해 발생하는 문제와 해결 방법을 설명하시오.', 'HTTP는 각 요청을 독립적으로 처리해 이전 요청의 상태를 기억하지 못하므로 로그인 상태 유지 등이 어렵다. 이를 해결하기 위해 쿠키, 세션, 토큰(JWT) 등을 사용해 상태 정보를 저장하고 요청마다 함께 전달해 상태를 유지한다.', 'short-answer', NULL, NULL),
('network', '로드 밸런싱의 주요 알고리즘(라운드 로빈, 최소 연결 등)을 설명하시오.', '라운드 로빈은 요청을 서버에 순서대로 균등하게 분배한다. 최소 연결(Least Connection)은 현재 연결 수가 가장 적은 서버로 요청을 보낸다. IP 해시는 클라이언트 IP를 해싱해 항상 같은 서버로 보내 세션 유지에 유리하다. 가중치 라운드 로빈은 서버 성능에 따라 가중치를 부여해 트래픽을 배분한다.', 'short-answer', NULL, NULL),

-- ================= database =================
('database', '트랜잭션의 4가지 특성(ACID)에 해당하지 않는 것은?', '가용성(Availability)', 'multiple-choice', ARRAY['원자성(Atomicity)', '일관성(Consistency)', '가용성(Availability)', '격리성(Isolation)'], 2),
('database', '트랜잭션 격리 수준(Isolation Level) 중 Dirty Read를 허용하는 가장 낮은 단계는?', 'Read Uncommitted', 'multiple-choice', ARRAY['Read Uncommitted', 'Read Committed', 'Repeatable Read', 'Serializable'], 0),
('database', 'SQL Injection 공격을 방지하는 방법으로 가장 적절하지 않은 것은?', '문자열을 그대로 쿼리에 concat', 'multiple-choice', ARRAY['Prepared Statement 사용', '사용자 입력값 검증', '문자열을 그대로 쿼리에 concat', '최소 권한 원칙 적용'], 2),
('database', '다음 중 NoSQL 데이터베이스의 특징으로 옳은 것은?', '수평적 확장(Scale-out)에 유리하다', 'multiple-choice', ARRAY['고정된 스키마를 강제한다', '수평적 확장(Scale-out)에 유리하다', '항상 ACID를 완벽히 보장한다', '조인 연산에 최적화되어 있다'], 1),
('database', '데이터베이스 인덱스(Index)에 대한 설명으로 옳지 않은 것은?', '인덱스를 많이 만들수록 항상 성능이 좋아진다', 'multiple-choice', ARRAY['조회 성능을 향상시킨다', '삽입/삭제/수정 시 오버헤드가 발생할 수 있다', '인덱스를 많이 만들수록 항상 성능이 좋아진다', 'B+Tree 구조를 주로 사용한다'], 2),
('database', '이상 현상(Anomaly)의 종류가 아닌 것은?', '격리 이상', 'multiple-choice', ARRAY['삽입 이상', '삭제 이상', '갱신 이상', '격리 이상'], 3),
('database', '정규화(Normalization)의 목적으로 가장 적절한 것은?', '데이터 중복을 줄이고 이상 현상을 방지한다', 'multiple-choice', ARRAY['데이터 중복을 줄이고 이상 현상을 방지한다', '조회 속도를 항상 극대화한다', '테이블 수를 최소화한다', '인덱스를 자동 생성한다'], 0),
('database', 'Redis에 대한 설명으로 옳지 않은 것은?', '관계형 데이터베이스처럼 복잡한 JOIN 연산에 최적화되어 있다', 'multiple-choice', ARRAY['인메모리 기반의 key-value 저장소이다', '디스크 기반 RDBMS보다 일반적으로 읽기/쓰기 속도가 빠르다', '캐시나 세션 저장소로 자주 사용된다', '관계형 데이터베이스처럼 복잡한 JOIN 연산에 최적화되어 있다'], 3),
('database', '기본키(Primary Key)와 후보키(Candidate Key)의 관계로 옳은 것은?', '기본키는 후보키 중 하나를 선정한 것이다', 'multiple-choice', ARRAY['기본키는 후보키 중 하나를 선정한 것이다', '후보키는 기본키보다 항상 개수가 적다', '기본키가 없어도 후보키는 존재할 수 없다', '후보키는 테이블당 하나만 존재한다'], 0),
('database', '저장 프로시저(Stored Procedure)의 장점이 아닌 것은?', '애플리케이션과 DB 로직의 완전한 분리로 이식성이 항상 높아짐', 'multiple-choice', ARRAY['네트워크 트래픽 감소', '재사용성 및 유지보수 용이', '애플리케이션과 DB 로직의 완전한 분리로 이식성이 항상 높아짐', '실행 계획 캐싱으로 성능 향상 가능'], 2),
('database', '트랜잭션의 ACID 특성을 각각 설명하시오.', '원자성(Atomicity)은 트랜잭션 내 작업이 전부 성공하거나 전부 실패해야 함을 의미한다. 일관성(Consistency)은 트랜잭션 전후로 데이터베이스가 일관된 상태를 유지해야 함을 의미한다. 격리성(Isolation)은 동시에 실행되는 트랜잭션들이 서로 영향을 주지 않아야 함을 의미한다. 지속성(Durability)은 커밋된 트랜잭션의 결과가 시스템 장애가 발생해도 영구적으로 반영되어야 함을 의미한다.', 'short-answer', NULL, NULL),
('database', '인덱스(Index)가 조회 성능을 향상시키는 원리와, 인덱스 사용 시 주의할 점을 설명하시오.', '인덱스는 B+Tree 등 정렬된 자료구조로 특정 컬럼 값을 빠르게 탐색할 수 있게 해 전체 테이블 스캔 없이 원하는 데이터 위치를 O(log n)에 찾을 수 있다. 다만 인덱스를 추가하면 삽입, 삭제, 갱신 시 인덱스도 함께 갱신해야 하므로 쓰기 성능이 저하되고 저장 공간을 추가로 사용하므로, 조회 빈도가 높고 카디널리티가 높은 컬럼 위주로 신중히 생성해야 한다.', 'short-answer', NULL, NULL),
('database', 'SQL과 NoSQL의 차이점을 설명하고, 각각 어떤 상황에 적합한지 설명하시오.', 'SQL(관계형 DB)은 고정된 스키마와 테이블 간 관계를 기반으로 하며 ACID 트랜잭션을 강하게 보장해 정합성이 중요한 금융, 주문 시스템 등에 적합하다. NoSQL은 스키마가 유연하고 수평 확장이 쉬워 대용량 트래픽, 비정형 데이터, 빠른 개발 속도가 필요한 서비스에 적합하지만 일반적으로 일관성보다 가용성/확장성에 무게를 둔다.', 'short-answer', NULL, NULL),
('database', 'SQL Injection이 발생하는 원리와 방어 방법을 설명하시오.', 'SQL Injection은 사용자 입력값을 검증 없이 쿼리 문자열에 그대로 결합할 때, 공격자가 입력값에 SQL 구문을 삽입해 의도치 않은 쿼리를 실행시키는 공격이다. Prepared Statement(바인딩 변수) 사용, 입력값 검증 및 이스케이프 처리, ORM 사용, 최소 권한의 DB 계정 사용 등으로 방어할 수 있다.', 'short-answer', NULL, NULL),
('database', '정규화와 반정규화(De-normalization)의 차이 및 각각을 사용하는 이유를 설명하시오.', '정규화는 테이블을 분해해 데이터 중복과 이상 현상을 줄이는 과정이다. 반정규화는 조회 성능을 높이기 위해 의도적으로 중복 데이터를 허용하거나 테이블을 통합하는 과정이다. 정규화는 데이터 무결성이 중요할 때, 반정규화는 잦은 조인으로 인한 성능 저하를 줄이고 싶을 때 사용한다.', 'short-answer', NULL, NULL),

-- ================= os =================
('os', '프로세스와 스레드의 차이에 대한 설명으로 옳은 것은?', '스레드는 같은 프로세스 내에서 Stack을 제외한 영역을 공유한다', 'multiple-choice', ARRAY['스레드는 독립된 메모리 공간을 가진다', '프로세스는 동일 프로세스 내 다른 프로세스와 Code, Data, Heap 영역을 공유한다', '스레드는 같은 프로세스 내에서 Stack을 제외한 영역을 공유한다', '프로세스 간 통신은 스레드 간 통신보다 항상 빠르다'], 2),
('os', '데드락(Deadlock) 발생의 4가지 필요조건이 아닌 것은?', '병행성', 'multiple-choice', ARRAY['상호 배제', '점유와 대기', '비선점', '병행성'], 3),
('os', 'CPU 스케줄링 알고리즘 중 실행 시간이 짧은 작업에 우선순위를 주는 것은?', 'SJF', 'multiple-choice', ARRAY['FCFS', 'SJF', 'Round Robin', 'Priority Scheduling'], 1),
('os', '세마포어(Semaphore)와 뮤텍스(Mutex)의 차이로 옳은 것은?', '뮤텍스는 소유 개념이 있어 잠근 주체만 해제할 수 있다', 'multiple-choice', ARRAY['뮤텍스는 여러 프로세스/스레드가 동시에 접근할 수 있는 카운터 기반 동기화 도구이다', '세마포어는 0과 1만 가질 수 있다', '뮤텍스는 소유 개념이 있어 잠근 주체만 해제할 수 있다', '세마포어는 상호배제만을 위해 사용된다'], 2),
('os', '페이지 교체 알고리즘 중 가장 오랫동안 사용되지 않은 페이지를 교체하는 것은?', 'LRU', 'multiple-choice', ARRAY['FIFO', 'LRU', 'Optimal', 'LFU'], 1),
('os', '페이징(Paging)과 세그멘테이션(Segmentation)에 대한 설명으로 옳은 것은?', '세그멘테이션은 논리적 의미 단위로 메모리를 나눈다', 'multiple-choice', ARRAY['페이징은 가변 크기 단위로 메모리를 나눈다', '세그멘테이션은 논리적 의미 단위로 메모리를 나눈다', '페이징은 외부 단편화를 유발한다', '세그멘테이션은 내부 단편화만 발생시킨다'], 1),
('os', '인터럽트(Interrupt)에 대한 설명으로 옳지 않은 것은?', '인터럽트 발생 시 현재 프로세스의 상태는 저장되지 않는다', 'multiple-choice', ARRAY['CPU가 현재 작업을 중단하고 처리해야 할 이벤트를 알리는 신호이다', '하드웨어 인터럽트와 소프트웨어 인터럽트(트랩)로 나뉜다', '인터럽트 발생 시 현재 프로세스의 상태는 저장되지 않는다', '인터럽트 벡터를 통해 해당 처리 루틴을 찾는다'], 2),
('os', 'Context Switching(문맥 교환)에 대한 설명으로 옳은 것은?', 'CPU가 한 프로세스에서 다른 프로세스로 전환될 때 이전 프로세스의 상태를 PCB에 저장하고 다음 프로세스의 상태를 복원하는 과정이다', 'multiple-choice', ARRAY['CPU가 한 프로세스에서 다른 프로세스로 전환될 때 이전 프로세스의 상태를 PCB에 저장하고 다음 프로세스의 상태를 복원하는 과정이다', '문맥 교환은 오버헤드가 전혀 없다', '스레드 간 문맥 교환은 프로세스 간보다 항상 느리다', '문맥 교환은 스케줄러와 무관하다'], 0),
('os', '경쟁 상태(Race Condition)를 방지하기 위한 방법으로 적절하지 않은 것은?', '모든 스레드를 동시에 실행하여 속도로 해결', 'multiple-choice', ARRAY['임계 구역(Critical Section)에 대한 상호 배제 적용', '세마포어나 뮤텍스를 이용한 동기화', '모든 스레드를 동시에 실행하여 속도로 해결', '락(Lock)을 이용한 자원 접근 제어'], 2),
('os', '시스템 콜(System Call) 중 새로운 프로세스를 생성하는 것은?', 'fork', 'multiple-choice', ARRAY['exec', 'wait', 'fork', 'exit'], 2),
('os', '프로세스와 스레드의 차이를 메모리 구조 관점에서 설명하시오.', '프로세스는 운영체제로부터 독립된 메모리 공간(Code, Data, Heap, Stack)을 할당받아 실행되는 프로그램 단위이다. 스레드는 하나의 프로세스 내에서 실행되는 흐름의 단위로, 같은 프로세스에 속한 스레드들은 Code, Data, Heap 영역은 공유하지만 각자 독립된 Stack과 레지스터를 가진다. 이 때문에 스레드 간 통신은 프로세스 간 통신보다 비용이 적다.', 'short-answer', NULL, NULL),
('os', '데드락(Deadlock)이 발생하기 위한 4가지 필요조건을 설명하시오.', '상호 배제(자원을 한 번에 하나의 프로세스만 사용), 점유와 대기(자원을 가진 채 다른 자원을 기다림), 비선점(다른 프로세스의 자원을 강제로 뺏을 수 없음), 원형 대기(프로세스들이 순환 형태로 서로의 자원을 기다림)의 네 조건이 모두 충족될 때 데드락이 발생한다.', 'short-answer', NULL, NULL),
('os', '뮤텍스와 세마포어의 차이를 설명하시오.', '뮤텍스는 하나의 자원에 대해 하나의 스레드만 접근을 허용하는 락으로, 소유 개념이 있어 잠근 스레드만 해제할 수 있다. 세마포어는 정수 카운터를 이용해 동시에 접근 가능한 자원의 개수를 제어하며, 상호배제뿐 아니라 프로세스 간 동기화(신호 전달)에도 사용될 수 있고 잠근 주체가 아니어도 해제할 수 있다.', 'short-answer', NULL, NULL),
('os', '페이지 교체 알고리즘 중 LRU(Least Recently Used)의 동작 방식과 장단점을 설명하시오.', 'LRU는 가장 최근에 사용되지 않은 페이지를 교체 대상으로 선택하는 알고리즘이다. 최근 참조 이력을 기반으로 하기 때문에 지역성(locality)을 잘 활용해 Optimal에 근접한 성능을 보인다. 다만 각 페이지의 참조 시각을 추적해야 하므로 구현 비용(스택이나 카운터 유지)이 발생한다.', 'short-answer', NULL, NULL),
('os', 'CPU 스케줄링 알고리즘 중 SJF(Shortest Job First)와 Round Robin의 차이와 각각의 장단점을 설명하시오.', 'SJF는 실행 시간이 가장 짧은 작업을 우선 처리해 평균 대기시간을 최소화하지만, 실행 시간이 긴 작업은 계속 순서가 밀리는 기아(Starvation) 문제가 발생할 수 있다. Round Robin은 각 프로세스에 동일한 타임 슬라이스를 할당해 순환 실행하는 방식으로 응답 시간이 균등하고 선점형 스케줄링에 적합하지만, 타임 슬라이스가 너무 작으면 문맥 교환 오버헤드가 커진다.', 'short-answer', NULL, NULL),

-- ================= data-structure =================
('data-structure', '배열(Array)과 연결 리스트(Linked List)의 차이로 옳은 것은?', '배열은 메모리 상에 연속적으로 저장되어 인덱스 접근이 O(1)이다', 'multiple-choice', ARRAY['배열은 삽입/삭제가 O(1)이다', '연결 리스트는 인덱스를 통한 임의 접근이 O(1)이다', '배열은 메모리 상에 연속적으로 저장되어 인덱스 접근이 O(1)이다', '연결 리스트는 메모리를 연속적으로 사용한다'], 2),
('data-structure', '스택(Stack)과 큐(Queue)에 대한 설명으로 옳은 것은?', '스택은 LIFO, 큐는 FIFO 구조이다', 'multiple-choice', ARRAY['스택은 FIFO, 큐는 LIFO 구조이다', '스택은 LIFO, 큐는 FIFO 구조이다', '둘 다 같은 방식으로 동작한다', '큐는 양쪽에서 삽입만 가능하다'], 1),
('data-structure', '해시 테이블(Hash Table)에서 충돌(Collision)을 해결하는 방법이 아닌 것은?', '이진 탐색(Binary Search)', 'multiple-choice', ARRAY['체이닝(Chaining)', '개방 주소법(Open Addressing)', '이진 탐색(Binary Search)', '리해싱(Rehashing)'], 2),
('data-structure', '이진 탐색 트리(Binary Search Tree)의 평균 탐색 시간 복잡도는?', 'O(log n)', 'multiple-choice', ARRAY['O(1)', 'O(log n)', 'O(n)', 'O(n log n)'], 1),
('data-structure', '힙(Heap) 자료구조에 대한 설명으로 옳은 것은?', '완전 이진 트리 기반으로 최댓값 또는 최솟값을 빠르게 찾을 수 있다', 'multiple-choice', ARRAY['항상 정렬된 배열이다', '완전 이진 트리 기반으로 최댓값 또는 최솟값을 빠르게 찾을 수 있다', '삽입과 삭제가 O(n)이다', '이진 탐색 트리와 동일한 구조이다'], 1),
('data-structure', 'B-Tree와 B+Tree의 차이로 옳은 것은?', 'B+Tree는 리프 노드에만 실제 데이터를 저장하고 리프 노드끼리 연결 리스트로 연결된다', 'multiple-choice', ARRAY['B+Tree는 리프 노드에만 실제 데이터를 저장하고 리프 노드끼리 연결 리스트로 연결된다', 'B-Tree는 리프 노드끼리 연결되어 있다', 'B+Tree는 내부 노드에도 데이터를 저장한다', '둘은 완전히 동일한 구조이다'], 0),
('data-structure', '트라이(Trie) 자료구조가 가장 효율적으로 사용되는 경우는?', '문자열 접두사(prefix) 검색', 'multiple-choice', ARRAY['정수 정렬', '문자열 접두사(prefix) 검색', '그래프 최단 경로 탐색', '우선순위 큐 구현'], 1),
('data-structure', 'ArrayList와 LinkedList에 대한 설명으로 옳은 것은?', 'ArrayList는 인덱스 접근이 O(1)이고 LinkedList는 중간 삽입/삭제가 상대적으로 유리하다', 'multiple-choice', ARRAY['ArrayList는 중간 삽입/삭제가 LinkedList보다 항상 빠르다', 'LinkedList는 인덱스 접근이 O(1)이다', 'ArrayList는 인덱스 접근이 O(1)이고 LinkedList는 중간 삽입/삭제가 상대적으로 유리하다', '둘 다 내부적으로 배열을 사용한다'], 2),
('data-structure', '트리(Tree)의 순회(Traversal) 방식 중 왼쪽-루트-오른쪽 순서로 방문하는 것은?', '중위 순회(Inorder)', 'multiple-choice', ARRAY['전위 순회(Preorder)', '중위 순회(Inorder)', '후위 순회(Postorder)', '레벨 순회(Level order)'], 1),
('data-structure', '다음 중 큐(Queue)를 이용해 구현하기 적합한 것은?', 'BFS(너비 우선 탐색)', 'multiple-choice', ARRAY['함수 호출 스택 관리', 'BFS(너비 우선 탐색)', '재귀 호출 처리', '괄호 짝 검사'], 1),
('data-structure', '배열과 연결 리스트의 시간 복잡도를 비교하고 각각 어떤 상황에 적합한지 설명하시오.', '배열은 메모리에 연속적으로 저장되어 인덱스를 통한 접근이 O(1)이지만, 중간 삽입/삭제는 뒤 요소를 이동해야 해 O(n)이 걸린다. 연결 리스트는 노드가 흩어져 있어 임의 접근이 O(n)이지만, 노드 참조만 변경하면 되므로 중간 삽입/삭제가 O(1)이다. 따라서 조회가 잦으면 배열, 삽입/삭제가 잦으면 연결 리스트가 유리하다.', 'short-answer', NULL, NULL),
('data-structure', '해시 테이블에서 해시 충돌이 발생하는 이유와 이를 해결하는 방법을 설명하시오.', '해시 함수는 무한한 입력을 유한한 버킷 개수로 매핑하기 때문에 서로 다른 키가 같은 해시값(버킷)으로 매핑되는 충돌이 발생할 수 있다. 체이닝은 같은 버킷에 연결 리스트 등으로 여러 값을 저장하는 방식이고, 개방 주소법은 충돌 시 다른 빈 버킷을 탐사해 저장하는 방식이다.', 'short-answer', NULL, NULL),
('data-structure', '이진 탐색 트리(BST)의 특징과, 편향된 트리가 될 경우 발생하는 문제를 설명하시오.', 'BST는 왼쪽 서브트리의 모든 값이 루트보다 작고 오른쪽 서브트리의 모든 값이 루트보다 크도록 구성된 트리로, 평균 탐색/삽입/삭제가 O(log n)이다. 그러나 데이터가 정렬된 순서로 삽입되는 등 특정 상황에서는 트리가 한쪽으로 치우친 연결 리스트 형태가 되어 시간 복잡도가 O(n)으로 저하될 수 있으며, 이를 해결하기 위해 AVL 트리나 레드-블랙 트리 같은 균형 이진 트리를 사용한다.', 'short-answer', NULL, NULL),
('data-structure', '힙(Heap)을 이용해 우선순위 큐를 구현할 때의 장점을 설명하시오.', '힙은 완전 이진 트리 구조로 최댓값(또는 최솟값)이 항상 루트에 위치하도록 유지되어, 최댓값/최솟값 조회가 O(1), 삽입과 삭제(루트 제거 후 재정렬)가 O(log n)에 가능하다. 배열로 정렬 상태를 유지하는 것보다 삽입/삭제 비용이 낮아 우선순위 큐 구현에 효율적이다.', 'short-answer', NULL, NULL),
('data-structure', 'B+Tree가 데이터베이스 인덱스로 널리 사용되는 이유를 설명하시오.', 'B+Tree는 모든 실제 데이터를 리프 노드에만 저장하고 리프 노드끼리 연결 리스트로 연결되어 있어, 범위 검색(range query) 시 리프 노드만 순차적으로 순회하면 되어 효율적이다. 또한 내부 노드에는 데이터 없이 인덱스 키만 저장해 하나의 디스크 블록(페이지)에 더 많은 키를 담을 수 있어 트리의 높이가 낮아지고, 이는 디스크 I/O 횟수를 줄여 대용량 데이터의 인덱스 구조로 적합하다.', 'short-answer', NULL, NULL),

-- ================= frontend (JavaScript 기준) =================
('frontend', '클로저(Closure)에 대한 설명으로 옳은 것은?', '함수가 선언될 당시의 렉시컬 스코프를 기억하여 함수 밖에서도 그 스코프의 변수에 접근할 수 있게 하는 함수이다', 'multiple-choice', ARRAY['함수가 선언될 당시의 렉시컬 스코프를 기억하여 함수 밖에서도 그 스코프의 변수에 접근할 수 있게 하는 함수이다', '클로저는 항상 전역 변수만 참조한다', '클로저는 자바스크립트에서 사용할 수 없는 개념이다', '클로저는 실행 즉시 메모리에서 해제된다'], 0),
('frontend', 'var, let, const의 차이로 옳지 않은 것은?', 'const로 선언한 객체의 프로퍼티는 변경할 수 없다', 'multiple-choice', ARRAY['var는 함수 스코프를 가진다', 'let과 const는 블록 스코프를 가진다', 'const로 선언한 객체의 프로퍼티는 변경할 수 없다', 'var는 호이스팅 시 undefined로 초기화된다'], 2),
('frontend', '== 와 === 연산자의 차이는?', '==는 타입을 변환해 값을 비교하고 ===는 타입과 값을 모두 비교한다', 'multiple-choice', ARRAY['==는 타입 변환 없이 비교하고 ===는 타입 변환 후 비교한다', '==는 타입을 변환해 값을 비교하고 ===는 타입과 값을 모두 비교한다', '둘의 동작은 완전히 동일하다', '===는 참조만 비교한다'], 1),
('frontend', '이벤트 루프(Event Loop)에서 마이크로태스크(Promise 콜백)와 매크로태스크(setTimeout)의 실행 순서로 옳은 것은?', '콜스택이 비워진 후 마이크로태스크 큐를 모두 비우고 나서 매크로태스크를 실행한다', 'multiple-choice', ARRAY['매크로태스크가 항상 먼저 실행된다', '콜스택이 비워진 후 마이크로태스크 큐를 모두 비우고 나서 매크로태스크를 실행한다', '등록된 순서와 무관하게 무작위로 실행된다', '마이크로태스크는 절대 실행되지 않는다'], 1),
('frontend', '프로토타입(Prototype)에 대한 설명으로 옳은 것은?', '객체는 자신의 프로토타입 체인을 통해 상위 객체의 프로퍼티와 메서드에 접근할 수 있다', 'multiple-choice', ARRAY['자바스크립트는 클래스 기반 상속만 지원한다', '객체는 자신의 프로토타입 체인을 통해 상위 객체의 프로퍼티와 메서드에 접근할 수 있다', '프로토타입 체인은 항상 한 단계로 끝난다', '__proto__는 모든 브라우저에서 사용이 금지되어 있다'], 1),
('frontend', '다음 중 원시 타입(Primitive Type)이 아닌 것은?', 'object', 'multiple-choice', ARRAY['string', 'number', 'boolean', 'object'], 3),
('frontend', '호이스팅(Hoisting)에 대한 설명으로 옳은 것은?', 'var로 선언한 변수와 함수 선언문은 스코프 최상단으로 끌어올려진 것처럼 동작한다', 'multiple-choice', ARRAY['var로 선언한 변수와 함수 선언문은 스코프 최상단으로 끌어올려진 것처럼 동작한다', 'let과 const는 호이스팅되지 않는다', '호이스팅은 ES6에서 새로 추가된 개념이다', '화살표 함수는 함수 선언문처럼 완전히 호이스팅된다'], 0),
('frontend', 'Promise의 상태(state)에 해당하지 않는 것은?', 'paused', 'multiple-choice', ARRAY['pending', 'fulfilled', 'rejected', 'paused'], 3),
('frontend', 'this 바인딩에 대한 설명으로 옳은 것은?', '일반 함수의 this는 호출 방식에 따라 동적으로 결정된다', 'multiple-choice', ARRAY['화살표 함수는 자신만의 this를 가지며 선언 시점의 상위 스코프 this를 사용하지 않는다', '일반 함수의 this는 호출 방식에 따라 동적으로 결정된다', 'call, apply, bind로는 this를 변경할 수 없다', '화살표 함수는 call로 this를 바꿀 수 있다'], 1),
('frontend', '다음 중 얕은 복사(Shallow Copy)에 대한 설명으로 옳은 것은?', '최상위 프로퍼티만 복사하고 중첩 객체는 참조를 공유한다', 'multiple-choice', ARRAY['중첩된 객체까지 모두 새로운 참조로 복사한다', '최상위 프로퍼티만 복사하고 중첩 객체는 참조를 공유한다', '원본과 복사본이 완전히 독립적이다', '배열에는 적용할 수 없는 개념이다'], 1),
('frontend', '클로저(Closure)의 개념과 실제 활용 예시를 설명하시오.', '클로저는 함수가 자신이 선언된 렉시컬 환경(스코프)을 기억해, 함수가 외부에서 호출되더라도 그 환경의 변수에 접근할 수 있게 하는 현상이다. 예를 들어 카운터 함수를 만들 때 내부 변수를 외부에서 직접 접근하지 못하게 캡슐화하면서도, 반환된 내부 함수를 통해서만 그 변수를 읽고 수정하게 하는 모듈 패턴이나 데이터 은닉에 활용된다.', 'short-answer', NULL, NULL),
('frontend', '이벤트 루프(Event Loop)의 동작 방식을 콜스택, 태스크 큐, 마이크로태스크 큐 관점에서 설명하시오.', '자바스크립트는 싱글 스레드로 콜스택에서 코드를 순차 실행한다. 비동기 작업(setTimeout, fetch 등)이 완료되면 콜백은 태스크 큐(매크로태스크) 또는 프로미스의 경우 마이크로태스크 큐에 쌓인다. 이벤트 루프는 콜스택이 완전히 비었을 때, 먼저 마이크로태스크 큐의 작업을 모두 처리한 뒤 매크로태스크 큐에서 하나를 꺼내 실행하는 과정을 반복한다.', 'short-answer', NULL, NULL),
('frontend', 'var, let, const의 차이를 스코프와 호이스팅 관점에서 설명하시오.', 'var는 함수 스코프를 가지며 호이스팅 시 undefined로 초기화되어 선언 전에도 접근하면 undefined가 반환된다. let과 const는 블록 스코프를 가지며 호이스팅되지만 초기화 전까지 Temporal Dead Zone에 놓여 접근 시 에러가 발생한다. const는 재할당이 금지되지만, 객체나 배열을 가리키는 경우 내부 프로퍼티 값 자체는 변경할 수 있다.', 'short-answer', NULL, NULL),
('frontend', '얕은 복사(Shallow Copy)와 깊은 복사(Deep Copy)의 차이를 설명하시오.', '얕은 복사는 객체의 최상위 프로퍼티만 새로운 메모리에 복사하고, 프로퍼티 값이 객체나 배열이면 그 참조만 복사해 원본과 복사본이 중첩 객체를 공유한다. 깊은 복사는 중첩된 객체까지 재귀적으로 모두 새로운 참조로 복사해 원본과 복사본이 완전히 독립적이다. 자바스크립트에서는 spread 연산자나 Object.assign은 얕은 복사, structuredClone이나 JSON 직렬화, 재귀 함수 등을 깊은 복사에 사용한다.', 'short-answer', NULL, NULL),
('frontend', '프로토타입 체인(Prototype Chain)의 동작 원리를 설명하시오.', '자바스크립트 객체는 내부적으로 [[Prototype]](또는 __proto__)이라는 다른 객체에 대한 참조를 가진다. 어떤 프로퍼티나 메서드를 객체에서 찾을 때, 자기 자신에게 없으면 이 참조를 따라 상위 프로토타입 객체를 순차적으로 탐색하며, 최상위 Object.prototype까지 가도 없으면 undefined를 반환한다. 이 연쇄적인 탐색 구조를 프로토타입 체인이라 하며, 자바스크립트의 상속 메커니즘의 기반이 된다.', 'short-answer', NULL, NULL);
